(1, 1, 'TRANSLATE_TO_VN', '「おはようございます」 (ohayou gozaimasu) nghĩa là gì?', NULL, NULL, '{"kana": "おはようございます", "romaji": "ohayou gozaimasu", "vn": "chào buổi sáng (lịch sự)", "teachAudio": "/uploads/audios/words/ohayou-gozaimasu.mp3", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}}}'),
(2, 1, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/ohayou-gozaimasu.mp3', NULL, '{"romaji": "ohayou gozaimasu", "vn": "chào buổi sáng (lịch sự)", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}, "おやすみなさい": {"r": "oyasuminasai", "v": "chúc ngủ ngon"}, "ありがとうございます": {"r": "arigatou gozaimasu", "v": "cảm ơn (lịch sự)"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}, "どういたしまして": {"r": "dou itashimashite", "v": "không có chi"}}}'),
(3, 1, 'TRANSLATE_TO_VN', '「おはよう」 (ohayou) nghĩa là gì?', NULL, NULL, '{"kana": "おはよう", "romaji": "ohayou", "vn": "chào buổi sáng (thân mật)", "teachAudio": "/uploads/audios/words/ohayou.mp3", "glossary": {"おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}}}'),
(4, 1, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/ohayou.mp3', NULL, '{"romaji": "ohayou", "vn": "chào buổi sáng (thân mật)", "glossary": {"おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}, "おやすみなさい": {"r": "oyasuminasai", "v": "chúc ngủ ngon"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}, "ごめんなさい": {"r": "gomen nasai", "v": "tôi xin lỗi"}}}'),
