(6, 1, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/konnichiwa.mp3', NULL, '{"romaji": "konnichiwa", "vn": "xin chào (ban ngày)", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}, "こんにちは": {"r": "konnichiwa", "v": "xin chào (ban ngày)"}, "こんばんは": {"r": "konbanwa", "v": "chào buổi tối"}, "ありがとうございます": {"r": "arigatou gozaimasu", "v": "cảm ơn (lịch sự)"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}}}'),
(7, 1, 'TRANSLATE_TO_VN', '「こんばんは」 (konbanwa) nghĩa là gì?', NULL, NULL, '{"kana": "こんばんは", "romaji": "konbanwa", "vn": "chào buổi tối", "teachAudio": "/uploads/audios/words/konbanwa.mp3", "glossary": {"こんばんは": {"r": "konbanwa", "v": "chào buổi tối"}}}'),
