(11, 1, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Chào buổi sáng ạ, thưa thầy.', '/uploads/audios/sentences/sensei-ohayou-gozaimasu.mp3', '/uploads/images/vocab/ohayou-gozaimasu.png', '{"romaji": "Sensei, ohayou gozaimasu.", "vn": "Chào buổi sáng ạ, thưa thầy.", "jp": "せんせい、おはようございます。", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}}}'),
(12, 1, 'TRANSLATE_TO_VN', 'Câu 「せんせい、おはようございます。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Sensei, ohayou gozaimasu.", "jp": "せんせい、おはようございます。", "vn": "Chào buổi sáng ạ, thưa thầy.", "teachAudio": "/uploads/audios/sentences/sensei-ohayou-gozaimasu.mp3", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}}}'),
(13, 1, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: せんせい、おはようございます。', '/uploads/audios/sentences/sensei-ohayou-gozaimasu.mp3', '/uploads/images/vocab/ohayou-gozaimasu.png', '{"romaji": "Sensei, ohayou gozaimasu.", "vn": "Chào buổi sáng ạ, thưa thầy.", "jp": "せんせい、おはようございます。", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}}}'),
(14, 1, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Xin chào mọi người.', '/uploads/audios/sentences/minasan-konnichiwa.mp3', '/uploads/images/vocab/konnichiwa.png', '{"romaji": "Minasan, konnichiwa.", "vn": "Xin chào mọi người.", "jp": "みなさん、こんにちは。", "glossary": {"こんにちは": {"r": "konnichiwa", "v": "xin chào (ban ngày)"}}}'),
(15, 1, 'TRANSLATE_TO_VN', 'Câu 「みなさん、こんにちは。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Minasan, konnichiwa.", "jp": "みなさん、こんにちは。", "vn": "Xin chào mọi người.", "teachAudio": "/uploads/audios/sentences/minasan-konnichiwa.mp3", "glossary": {"こんにちは": {"r": "konnichiwa", "v": "xin chào (ban ngày)"}}}'),
(16, 2, 'TRANSLATE_TO_VN', '「ありがとうございます」 (arigatou gozaimasu) nghĩa là gì?', NULL, NULL, '{"kana": "ありがとうございます", "romaji": "arigatou gozaimasu", "vn": "cảm ơn (lịch sự)", "teachAudio": "/uploads/audios/words/arigatou-gozaimasu.mp3", "glossary": {"ありがとうございます": {"r": "arigatou gozaimasu", "v": "cảm ơn (lịch sự)"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}}}'),
(17, 2, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/arigatou-gozaimasu.mp3', NULL, '{"romaji": "arigatou gozaimasu", "vn": "cảm ơn (lịch sự)", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}, "こんばんは": {"r": "konbanwa", "v": "chào buổi tối"}, "ありがとうございます": {"r": "arigatou gozaimasu", "v": "cảm ơn (lịch sự)"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}}}'),
(18, 2, 'TRANSLATE_TO_VN', '「ありがとう」 (arigatou) nghĩa là gì?', NULL, NULL, '{"kana": "ありがとう", "romaji": "arigatou", "vn": "cảm ơn (thân mật)", "teachAudio": "/uploads/audios/words/arigatou.mp3", "glossary": {"ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}}}'),
(19, 2, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/arigatou.mp3', NULL, '{"romaji": "arigatou", "vn": "cảm ơn (thân mật)", "glossary": {"おはようございます": {"r": "ohayou gozaimasu", "v": "chào buổi sáng (lịch sự)"}, "おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}, "おやすみなさい": {"r": "oyasuminasai", "v": "chúc ngủ ngon"}, "ありがとうございます": {"r": "arigatou gozaimasu", "v": "cảm ơn (lịch sự)"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}}}'),
(20, 2, 'TRANSLATE_TO_VN', '「どういたしまして」 (dou itashimashite) nghĩa là gì?', NULL, NULL, '{"kana": "どういたしまして", "romaji": "dou itashimashite", "vn": "không có chi", "teachAudio": "/uploads/audios/words/dou-itashimashite.mp3", "glossary": {"どういたしまして": {"r": "dou itashimashite", "v": "không có chi"}}}'),
(21, 2, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/dou-itashimashite.mp3', NULL, '{"romaji": "dou itashimashite", "vn": "không có chi", "glossary": {"おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}, "こんにちは": {"r": "konnichiwa", "v": "xin chào (ban ngày)"}, "どういたしまして": {"r": "dou itashimashite", "v": "không có chi"}, "すみません": {"r": "sumimasen", "v": "xin lỗi / cho hỏi"}}}'),
