(187, 12, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Bạn là sinh viên phải không?', '/uploads/audios/sentences/anata-wa-gakusei-desu-ka.mp3', '/uploads/images/vocab/gakusei.png', '{"romaji": "Anata wa gakusei desu ka.", "vn": "Bạn là sinh viên phải không?", "jp": "あなたはがくせいですか。", "glossary": {"あなた": {"r": "anata", "v": "bạn"}, "がくせい": {"r": "gakusei", "v": "học sinh, sinh viên"}}}'),
(188, 12, 'TRANSLATE_TO_VN', 'Câu 「あなたはがくせいですか。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Anata wa gakusei desu ka.", "jp": "あなたはがくせいですか。", "vn": "Bạn là sinh viên phải không?", "teachAudio": "/uploads/audios/sentences/anata-wa-gakusei-desu-ka.mp3", "glossary": {"あなた": {"r": "anata", "v": "bạn"}, "がくせい": {"r": "gakusei", "v": "học sinh, sinh viên"}}}'),
