(190, 12, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Vâng, đúng vậy.', '/uploads/audios/sentences/hai-sou-desu.mp3', '/uploads/images/vocab/sou-desu.png', '{"romaji": "Hai, sou desu.", "vn": "Vâng, đúng vậy.", "jp": "はい、そうです。", "glossary": {"はい": {"r": "hai", "v": "vâng, đúng vậy"}, "そうです": {"r": "sou desu", "v": "đúng vậy"}}}'),
(191, 12, 'TRANSLATE_TO_VN', 'Câu 「はい、そうです。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Hai, sou desu.", "jp": "はい、そうです。", "vn": "Vâng, đúng vậy.", "teachAudio": "/uploads/audios/sentences/hai-sou-desu.mp3", "glossary": {"はい": {"r": "hai", "v": "vâng, đúng vậy"}, "そうです": {"r": "sou desu", "v": "đúng vậy"}}}'),
(192, 12, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Người kia là ai vậy?', '/uploads/audios/sentences/ano-hito-wa-dare-desu-ka.mp3', '/uploads/images/vocab/ano-hito.png', '{"romaji": "Ano hito wa dare desu ka.", "vn": "Người kia là ai vậy?", "jp": "あのひとはだれですか。", "glossary": {"あのひと": {"r": "ano hito", "v": "người kia"}, "だれ": {"r": "dare", "v": "ai"}, "の": {"r": "no", "v": "của (nối 2 danh từ)"}}}'),
(193, 12, 'TRANSLATE_TO_VN', 'Câu 「あのひとはだれですか。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Ano hito wa dare desu ka.", "jp": "あのひとはだれですか。", "vn": "Người kia là ai vậy?", "teachAudio": "/uploads/audios/sentences/ano-hito-wa-dare-desu-ka.mp3", "glossary": {"あのひと": {"r": "ano hito", "v": "người kia"}, "だれ": {"r": "dare", "v": "ai"}, "の": {"r": "no", "v": "của (nối 2 danh từ)"}}}'),
(194, 13, 'TRANSLATE_TO_VN', '「じゃありません」 (ja arimasen) nghĩa là gì?', NULL, NULL, '{"kana": "じゃありません", "romaji": "ja arimasen", "vn": "không phải là…", "teachAudio": "/uploads/audios/words/ja-arimasen.mp3", "glossary": {"じゃありません": {"r": "ja arimasen", "v": "không phải là…"}}}'),
(195, 13, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/ja-arimasen.mp3', NULL, '{"romaji": "ja arimasen", "vn": "không phải là…", "glossary": {"わたし": {"r": "watashi", "v": "tôi"}, "なまえ": {"r": "namae", "v": "tên"}, "ベトナム": {"r": "betonamu", "v": "Việt Nam"}, "じゃありません": {"r": "ja arimasen", "v": "không phải là…"}}}'),
(196, 13, 'TRANSLATE_TO_VN', '「ではありません」 (dewa arimasen) nghĩa là gì?', NULL, NULL, '{"kana": "ではありません", "romaji": "dewa arimasen", "vn": "không phải là… (trang trọng)", "teachAudio": "/uploads/audios/words/dewa-arimasen.mp3", "glossary": {"ではありません": {"r": "dewa arimasen", "v": "không phải là… (trang trọng)"}}}'),
(197, 13, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/dewa-arimasen.mp3', NULL, '{"romaji": "dewa arimasen", "vn": "không phải là… (trang trọng)", "glossary": {"あのひと": {"r": "ano hito", "v": "người kia"}, "ベトナム": {"r": "betonamu", "v": "Việt Nam"}, "アメリカ": {"r": "amerika", "v": "Mỹ"}, "ではありません": {"r": "dewa arimasen", "v": "không phải là… (trang trọng)"}, "の": {"r": "no", "v": "của (nối 2 danh từ)"}}}'),
(198, 13, 'TRANSLATE_TO_VN', '「ちがいます」 (chigaimasu) nghĩa là gì?', NULL, NULL, '{"kana": "ちがいます", "romaji": "chigaimasu", "vn": "không phải, bạn nhầm rồi", "teachAudio": "/uploads/audios/words/chigaimasu.mp3", "glossary": {"ちがいます": {"r": "chigaimasu", "v": "không phải, bạn nhầm rồi"}}}'),
(199, 13, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/chigaimasu.mp3', NULL, '{"romaji": "chigaimasu", "vn": "không phải, bạn nhầm rồi", "glossary": {"にほん": {"r": "nihon", "v": "Nhật Bản"}, "アメリカ": {"r": "amerika", "v": "Mỹ"}, "かんこく": {"r": "kankoku", "v": "Hàn Quốc"}, "ちがいます": {"r": "chigaimasu", "v": "không phải, bạn nhầm rồi"}}}'),
