(208, 13, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: わたしはにほんじんじゃありません。', '/uploads/audios/sentences/watashi-wa-nihonjin-ja-arimasen.mp3', '/uploads/images/vocab/ja-arimasen.png', '{"romaji": "Watashi wa nihonjin ja arimasen.", "vn": "Tôi không phải người Nhật.", "jp": "わたしはにほんじんじゃありません。", "glossary": {"わたし": {"r": "watashi", "v": "tôi"}, "にほん": {"r": "nihon", "v": "Nhật Bản"}, "にほんじん": {"r": "nihonjin", "v": "người Nhật"}, "じゃありません": {"r": "ja arimasen", "v": "không phải là…"}}}'),
(209, 13, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Không, không phải vậy.', '/uploads/audios/sentences/iie-chigaimasu.mp3', '/uploads/images/vocab/chigaimasu.png', '{"romaji": "Iie, chigaimasu.", "vn": "Không, không phải vậy.", "jp": "いいえ、ちがいます。", "glossary": {"いいえ": {"r": "iie", "v": "không"}, "ちがいます": {"r": "chigaimasu", "v": "không phải, bạn nhầm rồi"}}}'),
(210, 13, 'TRANSLATE_TO_VN', 'Câu 「いいえ、ちがいます。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Iie, chigaimasu.", "jp": "いいえ、ちがいます。", "vn": "Không, không phải vậy.", "teachAudio": "/uploads/audios/sentences/iie-chigaimasu.mp3", "glossary": {"いいえ": {"r": "iie", "v": "không"}, "ちがいます": {"r": "chigaimasu", "v": "không phải, bạn nhầm rồi"}}}'),
(211, 13, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Anh Tanaka không phải bác sĩ.', '/uploads/audios/sentences/tanaka-san-wa-isha-ja-arimasen.mp3', '/uploads/images/vocab/ja-arimasen.png', '{"romaji": "Tanaka-san wa isha ja arimasen.", "vn": "Anh Tanaka không phải bác sĩ.", "jp": "たなかさんはいしゃじゃありません。", "glossary": {"いしゃ": {"r": "isha", "v": "bác sĩ"}, "はい": {"r": "hai", "v": "vâng, đúng vậy"}, "じゃありません": {"r": "ja arimasen", "v": "không phải là…"}}}'),
