(1417, 98, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Tôi về Việt Nam bằng máy bay.', '/uploads/audios/sentences/hikouki-de-betonamu-e-kaerimasu.mp3', '/uploads/images/vocab/hikouki.png', '{"romaji": "Hikouki de Betonamu e kaerimasu.", "vn": "Tôi về Việt Nam bằng máy bay.", "jp": "ひこうきでベトナムへかえります。", "glossary": {"ベトナム": {"r": "betonamu", "v": "Việt Nam"}, "かえります": {"r": "kaerimasu", "v": "về nhà"}, "へ": {"r": "e", "v": "đến (chỉ hướng)"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "ひこうき": {"r": "hikouki", "v": "máy bay"}}}'),
