(1751, 123, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Hôm nay tôi bị sốt.', '/uploads/audios/sentences/kyou-wa-netsu-ga-arimasu.mp3', '/uploads/images/vocab/netsu.png', '{"romaji": "Kyou wa netsu ga arimasu.", "vn": "Hôm nay tôi bị sốt.", "jp": "きょうはねつがあります。", "glossary": {"あります": {"r": "arimasu", "v": "có (đồ vật)"}, "が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "きょう": {"r": "kyou", "v": "hôm nay"}, "ねつ": {"r": "netsu", "v": "sốt"}}}'),
(1752, 123, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: きょうはとてもつかれました。', '/uploads/audios/sentences/kyou-wa-totemo-tsukaremashita.mp3', '/uploads/images/vocab/tsukaremashita.png', '{"romaji": "Kyou wa totemo tsukaremashita.", "vn": "Hôm nay tôi rất mệt.", "jp": "きょうはとてもつかれました。", "glossary": {"した": {"r": "shita", "v": "phía dưới"}, "きょう": {"r": "kyou", "v": "hôm nay"}, "ました": {"r": "mashita", "v": "đã… (quá khứ)"}, "とても": {"r": "totemo", "v": "rất"}, "て": {"r": "te", "v": "tay"}, "つかれました": {"r": "tsukaremashita", "v": "mệt rồi"}}}'),
