(1754, 123, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/onaka.mp3', NULL, '{"romaji": "onaka", "vn": "bụng", "glossary": {"なか": {"r": "naka", "v": "bên trong"}, "はな": {"r": "hana", "v": "mũi"}, "あたま": {"r": "atama", "v": "đầu"}, "おなか": {"r": "onaka", "v": "bụng"}, "ねつ": {"r": "netsu", "v": "sốt"}}}'),
(1755, 123, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Đứa bé có đôi mắt to.', '/uploads/audios/sentences/kodomo-wa-me-ga-ookii-desu.mp3', NULL, '{"romaji": "Kodomo wa me ga ookii desu.", "vn": "Đứa bé có đôi mắt to.", "jp": "こどもはめがおおきいです。", "glossary": {"が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "こども": {"r": "kodomo", "v": "trẻ con"}, "おおきい": {"r": "ookii", "v": "to, lớn"}, "め": {"r": "me", "v": "mắt"}}}'),
